package com.example.examplemod.cargo.center;

import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
import java.util.*;

/** Financial and custody regression scenarios; real native packing still requires a game launcher. */
public final class MasterCityTradeCheck {
    private static int checks;
    private static void require(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
    private static void rejects(Runnable action,String message){boolean rejected=false;try{action.run();}catch(IllegalArgumentException expected){rejected=true;}require(rejected,message);}
    private static final MasterCityTradeBook.Accounts ACCOUNTS=new MasterCityTradeBook.Accounts(){public long maximum(){return 1_000_000;}public void dirty(){}};
    private static final class CatalogAccounts implements CargoCommerceBook.Accounts {
        final Map<OwnerRef,Long> balances=new HashMap<>();
        public long balance(OwnerRef owner){return balances.getOrDefault(owner,0L);}
        public boolean debit(OwnerRef owner,long amount){if(amount<0||amount>balance(owner))return false;balances.put(owner,balance(owner)-amount);return true;}
        public boolean canCredit(OwnerRef owner,long amount){return amount>=0&&balance(owner)<=Long.MAX_VALUE-amount;}
        public void credit(OwnerRef owner,long amount){if(!canCredit(owner,amount))throw new ArithmeticException();balances.put(owner,balance(owner)+amount);}
        public long maximum(){return 1_000_000;}public void dirty(){}
    }
    private static CompoundTag item(String id){var tag=new CompoundTag();tag.putString("id",id);return tag;}
    private static MasterCityTradeBook fixture(MasterCityTradeBook.Direction mode){var b=new MasterCityTradeBook(ACCOUNTS);b.time(1_000_000,100);b.bind(new MasterCityTradeBook.Binding(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),new CargoInfrastructure.Location(ResourceLocation.parse("minecraft:overworld"),BlockPos.ZERO),UUID.randomUUID()),null);b.configureBudget(1000,null);b.policy(new MasterCityTradeBook.Policy(UUID.randomUUID(),"Iron",item("minecraft:iron_ingot"),mode,100,200,50,100,5,10,50,false),null);b.enabled(true,null);return b;}
    private static MasterCityTradeBook restore(MasterCityTradeBook book){var restored=new MasterCityTradeBook(ACCOUNTS);restored.load(book.save());return restored;}
    public static void main(String[] args)throws Exception{
        var b=fixture(MasterCityTradeBook.Direction.EXPORT);var p=b.policies().getFirst();UUID cId=UUID.randomUUID();var c=b.createContract(cId,p.id(),50,"Foreign demand",2_000_000,null);
        require(p.demand(100,0,0)==0,"retained export goods cover city target and cannot trigger endless repeat procurement");require(p.demand(80,20,0)==0,"confirmed inbound goods cover the same shortage once");require(p.demand(10,20,90)==10,"new demand is capped by the remaining daily item quota");require(p.demand(Integer.MAX_VALUE,4096,0)==0,"large native stock cannot wrap signed arithmetic into an artificial shortage");
        require(b.allocated()==300&&b.balance()==300&&b.remainingBudget()==700,"contract reserves full goods and freight from bounded daily grant");
        require(b.createContract(cId,p.id(),50,"Foreign demand",2_000_000,null).equals(c)&&b.allocated()==300,"contract UUID replay cannot issue another grant");
        rejects(()->b.createContract(cId,p.id(),51,"Foreign demand",2_000_000,null),"same contract UUID cannot change quantity");
        require(!b.debit(1)&&b.balance()==300,"restricted account cannot be spent outside authorized supply");
        UUID supplyId=UUID.randomUUID(),offer=UUID.randomUUID();b.beginSupply(supplyId,cId,offer,20,1_000_000);
        require(b.contractRemaining(c)==30&&b.inbound(p.id())==20,"one supply reserves quantity against competing suppliers");
        rejects(()->b.beginSupply(supplyId,cId,UUID.randomUUID(),20,1_000_000),"supply UUID cannot substitute offer");
        try(var funding=b.funding(supplyId)){require(!b.debit(151),"supplier cannot exceed contracted goods/freight ceiling");require(b.debit(100)&&b.debit(20),"Cargo and separate road escrow share one bounded funding ceiling");require(!b.debit(31),"cumulative funding cannot exceed the supply ceiling");}
        require(!b.debit(1),"funding authority closes after synchronous Cargo call");b.dispatched(supplyId);
        b.credit(40);b.resolved(supplyId,10,40,true);
        require(b.balance()==220&&b.paid()==80&&b.receivedUnits()==10,"partial cancellation pays only proven delivery and refunds original escrow");
        require(b.contractRemaining(c)==40&&b.inbound(p.id())==0,"recovered units restore contract capacity without recounting delivered items");
        require(b.allocated()==300&&b.remainingBudget()==700,"refund never resets daily issuance allocation");
        b.resolved(supplyId,10,40,true);require(b.paid()==80&&b.receivedUnits()==10,"delivery receipt replay never pays or counts twice");
        var r=restore(b);r.resolved(supplyId,10,40,true);require(r.paid()==80&&r.balance()==220,"financial receipt survives restart in same save as budget");
        r.closeContract(cId,true,null);require(r.balance()==0&&r.contract(cId).orElseThrow().state()==MasterCityTradeBook.ContractState.EXPIRED,"expiration sinks unspent restricted grant, preserving completed payments");
        r.time(900_000,99);require(r.period()==100&&r.allocated()==300&&r.now()==1_000_000,"clock rollback cannot replenish daily allowance or rewind deadlines");
        r.time(3_000_000,101);require(r.period()==101&&r.allocated()==0&&r.balance()==0,"new real day grants an allowance, not cash or queued missed payouts");
        r.time(900_000_000,110);require(r.balance()==0&&r.remainingBudget()==1000,"server downtime does not accumulate missed daily grants");
        UUID next=UUID.randomUUID();r.createContract(next,p.id(),50,"Next demand",900_100_000,null);require(r.balance()==300,"new contract obtains one current-day bounded grant");
        rejects(()->r.policy(new MasterCityTradeBook.Policy(UUID.randomUUID(),"Duplicate",p.item(),p.direction(),1,10,1,1,1,2,0,false),null),"duplicate item policies cannot bypass item quotas or buy one deficit twice");
        rejects(()->new MasterCityTradeBook.Policy(UUID.randomUUID(),"Loop",p.item(),MasterCityTradeBook.Direction.BOTH,10,20,1,10,10,10,0,false),"crossed import/export prices are rejected");
        var active=fixture(MasterCityTradeBook.Direction.EXPORT);var ap=active.policies().getFirst();var ac=active.createContract(UUID.randomUUID(),ap.id(),10,"Old obligation",5_000_000,null);active.time(3_000_000,101);require(active.balance()==100&&active.contractAvailable(ac)==100&&active.allocated()==0,"period rollover preserves previously reserved obligations independently");
        rejects(()->active.bind(active.binding(),null),"changing physical binding cannot orphan active contracts");
        var imports=fixture(MasterCityTradeBook.Direction.IMPORT);var ip=imports.policies().getFirst();UUID batch=UUID.randomUUID();imports.beginImport(batch,ip.id(),10,null);require(imports.quotaUsed(ip.id())==10&&imports.createdUnits()==0,"durable intent consumes quota without claiming physical creation");
        var interrupted=restore(imports);require(interrupted.importBatch(batch).orElseThrow().state()==MasterCityTradeBook.ImportState.INTENT,"ledger-first crash restores unresolved intent");
        rejects(()->interrupted.beginImport(UUID.randomUUID(),ip.id(),10,null),"an unresolved intent cannot be automatically regenerated");
        rejects(()->interrupted.beginImport(batch,ip.id(),11,null),"import UUID cannot change quantity after restart");
        var custody=new MasterCityImportReceipts();require(custody.begin(batch,ip.item(),10)&&custody.locked(),"physical creation immediately locks every exposed handler side");
        require(!custody.begin(batch,ip.item(),10),"same physical receipt is a no-insertion replay");
        var chunkFirst=new MasterCityImportReceipts();chunkFirst.load(custody.save());require(chunkFirst.locked()&&batch.equals(chunkFirst.pending()),"chunk-first crash retains physical custody lock with receipt");
        require(!chunkFirst.durable(batch),"a new in-memory receipt cannot skip the physical chunk barrier");chunkFirst.durable(batch,true);var flushed=new MasterCityImportReceipts();flushed.load(chunkFirst.save());require(flushed.durable(batch)&&flushed.locked(),"loaded durable marker travels with the same locked physical receipt and avoids repeated full saves");chunkFirst.durable(batch,false);require(!chunkFirst.durable(batch),"a failed flush can remove the in-memory durability claim");
        rejects(()->chunkFirst.release(UUID.randomUUID()),"unrelated ledger receipt cannot release inventory");
        var receipt=chunkFirst.receipt(batch);receipt.putInt("Quantity",999);require(chunkFirst.receipt(batch).getInt("Quantity")==10,"external receipt reads cannot alter authoritative quantity");
        imports.importApplied(batch);imports.importApplied(batch);require(imports.createdUnits()==10,"creation observation counts once");UUID importOffer=UUID.randomUUID();imports.confirmImport(batch,importOffer,null);chunkFirst.release(batch);
        require(!chunkFirst.locked()&&imports.isImportOffer(importOffer),"confirmed physical batch releases to real machinery and freezes sink recipient");
        require(!chunkFirst.begin(batch,ip.item(),10),"extracted/previously confirmed batch can never mint again");
        var lockedOldChunk=new MasterCityImportReceipts();lockedOldChunk.load(custody.save());var confirmedLedger=restore(imports);require(confirmedLedger.importBatch(batch).orElseThrow().state()==MasterCityTradeBook.ImportState.CONFIRMED&&lockedOldChunk.locked(),"ledger-first release crash is distinguishable from a new import");lockedOldChunk.release(batch);require(!lockedOldChunk.locked(),"saved confirmed receipt safely reopens older locked chunk without item creation");
        var missingChunk=new MasterCityImportReceipts();require(!MasterCityImportReceipts.matches(missingChunk.receipt(batch),batch,ip.item(),10),"financial confirmation is not evidence that an older chunk contains the import");confirmedLedger.quarantineImport(batch,"Original physical receipt missing");require(confirmedLedger.hasOutstanding()&&confirmedLedger.importBatch(batch).orElseThrow().state()==MasterCityTradeBook.ImportState.QUARANTINED,"confirmed-finance/missing-chunk recovery blocks source without recreating stock");require(confirmedLedger.createdUnits()==10&&confirmedLedger.quotaUsed(ip.id())==10,"quarantine never releases goods quota or generates another batch");require(MasterCityImportReceipts.matches(custody.receipt(batch),batch,ip.item(),10),"restored original chunk receipt provides positive custody evidence");
        long shortageStart=imports.shortage(ip.id(),true);imports.time(imports.now()+123_000,100);require(imports.shortage(ip.id(),true)==shortageStart&&restore(imports).shortage(ip.id(),true)==shortageStart,"insurance import delay survives repeated checks and restart");imports.shortage(ip.id(),false);require(imports.shortage(ip.id(),true)==imports.now(),"resolved physical deficit resets the insurance timer");
        UUID revenue=UUID.randomUUID();imports.importSale(revenue,100);imports.importSale(revenue,100);require(imports.importRevenue()==100&&imports.balance()==0&&imports.allocated()==0,"import-sale sink is idempotent and never funds export budget");
        rejects(()->imports.importSale(revenue,101),"sink receipt cannot change value");var importedAgain=restore(imports);importedAgain.importSale(revenue,100);require(importedAgain.importRevenue()==100,"sink replay remains idempotent after restart");
        var partial=new MasterCityImportReceipts();UUID partialId=UUID.randomUUID();partial.begin(partialId,ip.item(),10);partial.partial(partialId,4);partial.release(partialId);require(partial.locked(),"partial insertion stays quarantined even after ordinary release");rejects(()->partial.resolve(partialId,""),"operator recovery requires an explicit reason");partial.resolve(partialId,"Inspected physical four items; quota remains spent");require(!partial.locked(),"explicit audit recovery unlocks without recreating missing units");
        var unknown=imports.save();unknown.putInt("Version",2);rejects(()->new MasterCityTradeBook(ACCOUNTS).load(unknown),"future financial format fails closed");var bad=imports.save();bad.putLong("Cash",-1);rejects(()->new MasterCityTradeBook(ACCOUNTS).load(bad),"negative restricted balances are rejected");var futureCustody=custody.save();futureCustody.putInt("Version",2);rejects(()->new MasterCityImportReceipts().load(futureCustody),"future custody format fails closed");
        var economy=new com.example.examplemod.economy.EconomyManager();UUID master=UUID.randomUUID();economy.masterTrade().bind(new MasterCityTradeBook.Binding(master,UUID.randomUUID(),UUID.randomUUID(),new CargoInfrastructure.Location(ResourceLocation.parse("minecraft:overworld"),BlockPos.ZERO),UUID.randomUUID()),null);economy.setMasterCity(master);var saved=economy.save(new CompoundTag(),null);require(saved.getUUID("MasterCity").equals(saved.getCompound("MasterCityTrade").getCompound("Binding").getUUID("City")),"global map master marker and trade binding persist together in the same financial save");
        var catalogAccounts=new CatalogAccounts();var buyer=OwnerRef.player(UUID.randomUUID());var citySeller=new OwnerRef(OwnerRef.Kind.CITY,imports.binding().city());catalogAccounts.balances.put(buyer,100L);var catalog=new CargoCommerceBook(catalogAccounts);catalog.publish(importOffer,UUID.randomUUID(),citySeller,imports.binding().warehouse(),ip.item(),ip.name(),10,10);UUID paidOrder=UUID.randomUUID();catalog.reserve(paidOrder,buyer,citySeller,paidOrder,importOffer,4,40,List.of());
        require(imports.closeImportListing(batch,UUID.randomUUID()).equals(importOffer)&&catalog.close(importOffer),"operator can retire a confirmed import's unsold listing");require(!catalog.offer(importOffer).orElseThrow().active()&&catalog.offer(importOffer).orElseThrow().remaining()==6,"closing an import does not delete remaining physical goods or offer capacity");require(catalog.order(paidOrder).orElseThrow().state()==CargoCommerceBook.State.HELD&&catalogAccounts.balance(buyer)==60,"closing stops new purchases while keeping funded delivery and escrow intact");require(imports.importBatch(batch).orElseThrow().state()==MasterCityTradeBook.ImportState.CONFIRMED&&imports.isImportOffer(importOffer)&&imports.quotaUsed(ip.id())==10,"retirement preserves physical proof, immutable sink recipient and spent creation quota");require(MasterCityTradeService.needsReceipt(catalog.offer(importOffer).orElseThrow(),catalog.orders(),importOffer),"rebind remains blocked by a funded order even after its listing closes");catalog.refundUnattempted(paidOrder);require(!MasterCityTradeService.needsReceipt(catalog.offer(importOffer).orElseThrow(),catalog.orders(),importOffer),"a closed unsold listing without pending orders no longer blocks rebind");var nextBinding=new MasterCityTradeBook.Binding(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),new CargoInfrastructure.Location(ResourceLocation.parse("minecraft:overworld"),new BlockPos(16,64,16)),UUID.randomUUID());imports.bind(nextBinding,null);require(imports.binding().equals(nextBinding)&&imports.importBatch(batch).orElseThrow().state()==MasterCityTradeBook.ImportState.CONFIRMED,"rebind retains the old confirmed receipt rather than resetting or recreating its goods");
        System.out.println("PASS: "+checks+" master-city budget, physical custody and crash-recovery checks");
    }
}
